'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var isUint64Array = require( '@stdlib/assert/is-uint64array' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var Uint64Array = require( './../lib' );


// FUNCTIONS //

/**
* Comparison function.
*
* @private
* @param {Uint64} a - first value for comparison
* @param {Uint64} b - second value for comparison
* @returns {number} comparison result
*/
function compareFcn( a, b ) {
	return a.lo - b.lo;
}


// MAIN //

bench( format( '%s:sort', pkg ), function benchmark( b ) {
	var arr;
	var out;
	var i;

	arr = new Uint64Array( 10 );

	// Benchmark worst case scenario (i.e., every element is compared and written back to the array)...
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.sort();
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isUint64Array( out ) ) {
		b.fail( 'should return a Uint64Array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::compare_function:sort', pkg ), function benchmark( b ) {
	var arr;
	var out;
	var i;

	arr = new Uint64Array( 10 );

	// Benchmark worst case scenario (i.e., every element is compared and written back to the array)...
	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		out = arr.sort( compareFcn );
		if ( typeof out !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isUint64Array( out ) ) {
		b.fail( 'should return a Uint64Array' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
